import{_ as n,c as t,o as a,ah as i}from"./chunks/framework.oAolcYhj.js";const r="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard.jpg",s="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_project.jpg",l="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_project_detail.jpg",h="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_tabs.jpg",d="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_overview.jpg",o="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_warranty.jpg",c="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_trench.jpg",g="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_trench_hover.jpg",u="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_conduit.jpg",m="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_node.jpg",b="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_address.jpg",p="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_area.jpg",R=JSON.parse('{"title":"4. Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/04-dashboard.md","filePath":"manual/teil-a-anwenderhandbuch/04-dashboard.md"}'),f={name:"manual/teil-a-anwenderhandbuch/04-dashboard.md"};function k(z,e,w,_,D,v){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="_4-dashboard" tabindex="-1">4. Dashboard <a class="header-anchor" href="#_4-dashboard" aria-label="Permalink to &quot;4. Dashboard&quot;">​</a></h1><p>Das <strong>Dashboard</strong> ist die zentrale Übersichtsseite von Qonnectra. Es fasst den dokumentierten Netzbestand eines Projekts in Kennzahlen und Diagrammen zusammen, damit Sie den Ausbauzustand ohne Umweg über Listen oder die Karte erfassen können. Nach der Anmeldung ist das Dashboard die Startansicht; später erreichen Sie es über die linke Navigation durch Klicken auf den Menüpunkt „Dashboard“ in der Gruppe „Info“.</p><p><img src="'+r+'" alt="Screenshot Dashboard" data-zoomable="true"></p><p>Alle Auswertungen beziehen sich auf das Projekt, das oben links in der Kopfzeile ausgewählt ist, und sind ausschließlich zur Ansicht bestimmt: Werte lassen sich hier nicht bearbeiten, eine Exportfunktion gibt es nicht.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Kennzahlen werden auf dem Server bis zu fünf Minuten zwischengespeichert. Daten, die Sie gerade in einer anderen Ansicht erfasst haben, erscheinen deshalb unter Umständen erst mit einigen Minuten Verzögerung – ein Neuladen der Seite beschleunigt das nicht.</p></div><h2 id="_4-1-projekt-auswahlen" tabindex="-1">4.1 Projekt auswählen <a class="header-anchor" href="#_4-1-projekt-auswahlen" aria-label="Permalink to &quot;4.1 Projekt auswählen&quot;">​</a></h2><p>Bevor Kennzahlen sichtbar werden, muss ein Projekt ausgewählt sein. Die Projektauswahl oben links in der Kopfzeile ist eine Kombination aus Eingabefeld und Auswahlliste: Über den Pfeil am rechten Rand öffnen Sie die Liste aller für Sie freigegebenen Projekte, über eine Eingabe in das Feld schränken Sie die Liste auf passende Namen ein. Mit dem Klick auf einen Eintrag wechseln Sie das Projekt; alle Karten und Diagramme werden daraufhin neu geladen.</p><p class="img-row"><img src="'+s+'" alt="Screenshot Dashboard mit Hervorhebung der Projektauswahl oben links in der Kopfzeile" data-zoomable="true"><img src="'+l+'" alt="Screenshot Ausschnittvergrößerung der geöffneten Projektliste in der Kopfzeile mit dem hervorgehobenen Eintrag „Testprojekt“" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Eingabe im Feld allein wählt nichts aus – erst der Klick auf einen Eintrag der Liste wechselt das Projekt. Solange kein Projekt gewählt ist, bleiben alle Kennzahlen auf Null und die Diagramme zeigen „Keine Daten verfügbar“.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Projektauswahl gilt für die gesamte Anwendung und bleibt beim Wechsel in eine andere Ansicht erhalten (siehe Kapitel <a href="./03-einstieg-und-anmeldung.html">Einstieg und Anmeldung</a>). Sind für Ihr Benutzerkonto keine Projekte freigegeben, erscheint anstelle des Feldes der Hinweis „Keine Projekte verfügbar“.</p></div><h2 id="_4-2-reiter-im-dashboard" tabindex="-1">4.2 Reiter im Dashboard <a class="header-anchor" href="#_4-2-reiter-im-dashboard" aria-label="Permalink to &quot;4.2 Reiter im Dashboard&quot;">​</a></h2><p>Unterhalb der Kopfzeile stehen sechs Reiter (Tabs): „Übersicht“ mit den Kennzahlen aller Datenbereiche auf einen Blick sowie „Trasse“, „Rohre“, „Netzknoten“, „Adressen“ und „Gebiete“ mit den Auswertungen des jeweiligen Bereichs. Der aktive Reiter ist farbig hervorgehoben. Alle Auswertungen werden beim Öffnen des Dashboards gemeinsam geladen, der Wechsel zwischen den Reitern lädt also keine Daten nach.</p><p><img src="'+h+'" alt="Screenshot Dashboard mit Hervorhebung der Reiterleiste oberhalb der Inhaltsfläche" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Bei einem schmalen Fenster sind nicht alle sechs Beschriftungen gleichzeitig zu sehen. Die Reiterleiste lässt sich dann waagerecht verschieben, zeigt dabei aber keinen Rollbalken. Auch die Inhaltsfläche darunter ist scrollbar – die unteren Karten und Diagramme werden erst nach dem Scrollen sichtbar.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Liegen für ein Diagramm keine Werte vor, steht an seiner Stelle „Keine Daten verfügbar“. Das ist kein Fehler: Fehlt eine Angabe im Projekt durchgängig – etwa die Netzebene der Rohre –, bleibt das zugehörige Diagramm leer, während die übrigen gefüllt sind.</p></div><h3 id="_4-2-1-ubersicht" tabindex="-1">4.2.1 Übersicht <a class="header-anchor" href="#_4-2-1-ubersicht" aria-label="Permalink to &quot;4.2.1 Übersicht&quot;">​</a></h3><p>Der Reiter „Übersicht“ enthält sechs Karten. Jede nennt oben eine oder zwei große Kennzahlen und darunter die Aufschlüsselung als Liste; der farbige Balken im Hintergrund einer Zeile zeigt deren Anteil am größten Wert der Liste.</p><ul><li>„Trassenstatistik“ – Gesamtlänge aller Trassen, aufgeschlüsselt nach Verlegeart und Oberfläche</li><li>„Netzknotenstatistik“ – Anzahl aller Netzknoten, aufgeschlüsselt nach Knotentyp</li><li>„Rohrstatistiken“ – Gesamtlänge aller Rohre, aufgeschlüsselt nach Rohrtyp</li><li>„Adress-Statistiken“ – Adressen und Wohneinheiten gesamt, aufgeschlüsselt nach Ort</li><li>„Gebietsstatistiken“ – Anzahl und Gesamtfläche der Gebiete, aufgeschlüsselt nach Gebietstyp</li><li>„Gewährleistung“ – die als nächstes ablaufenden Gewährleistungsfristen</li></ul><p><img src="'+d+'" alt="Screenshot Dashboard mit Hervorhebung der Karten im Reiter „Übersicht“ in der Inhaltsfläche" data-zoomable="true"></p><p>Adressen ohne Ortsangabe und Gebiete ohne Typ erscheinen in ihrer Liste unter „Unbekannt“.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Alle Karten begrenzen die Höhe ihrer Liste. Sind mehr Zeilen vorhanden als angezeigt werden, scrollen Sie innerhalb der Karte nach unten.</p></div><h4 id="gewahrleistung" tabindex="-1">Gewährleistung <a class="header-anchor" href="#gewahrleistung" aria-label="Permalink to &quot;Gewährleistung&quot;">​</a></h4><p>Die Karte „Gewährleistung“ zeigt bis zu fünf Netzknoten, deren Gewährleistungsfrist als nächste abläuft, aufsteigend nach Datum sortiert. Je Eintrag stehen der Name des Netzknotens, die verbleibende Restlaufzeit und das Ablaufdatum. Die Einträge sind nach Dringlichkeit farbig hinterlegt:</p><ul><li>rot: weniger als 30 Tage Restlaufzeit</li><li>gelb: weniger als 90 Tage Restlaufzeit</li><li>grün: 90 Tage Restlaufzeit oder mehr</li></ul><p>Sind für das Projekt keine Fristen hinterlegt, erscheint stattdessen „Keine Garantien laufen bald ab“.</p><p><img src="'+o+'" alt="Screenshot Dashboard mit Hervorhebung der Karte „Gewährleistung“ und ihren farbig hinterlegten Einträgen unten rechts in der Inhaltsfläche" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Karte ist keine vollständige Liste aller Gewährleistungsfristen des Projekts – sie zeigt höchstens fünf Netzknoten, bereits abgelaufene Fristen erscheinen nicht mehr. Die Frist eines einzelnen Netzknotens finden Sie in dessen Info-Box im Reiter „Eigenschaften“ (siehe Kapitel <a href="./05-karte.html">Karte</a>).</p></div><h3 id="_4-2-2-trasse" tabindex="-1">4.2.2 Trasse <a class="header-anchor" href="#_4-2-2-trasse" aria-label="Permalink to &quot;4.2.2 Trasse&quot;">​</a></h3><p>Im Reiter „Trasse“ finden Sie acht waagerechte Balkendiagramme zu den Trassen des Projekts:</p><ul><li>„Gesamtlänge pro Oberfläche“</li><li>„Gesamtlänge pro Verlegeart“</li><li>„Durchschnittliche Hausanschlusslänge“</li><li>„Länge gefördert“ – über die als gefördert gekennzeichneten Trassen</li><li>„Länge Eigenleistung“ – über die in Eigenleistung erbrachten Trassen</li><li>„Gesamtlänge pro Status“</li><li>„Gesamtlänge pro Netzebene“</li><li>„Längsten Trassen im Netz“ – die fünf längsten Trassen, beschriftet mit Verlegeart und Oberfläche</li></ul><p class="img-row"><img src="'+c+'" alt="Screenshot Dashboard mit Hervorhebung der Diagramme im Reiter „Trasse“ in der Inhaltsfläche" data-zoomable="true"><img src="'+g+'" alt="Screenshot Ausschnittvergrößerung des Diagramms „Gesamtlänge pro Oberfläche“ mit dem Tooltip über einem Balken" data-zoomable="true"></p><p>Genaue Werte lesen Sie einzeln ab: Zeigen Sie mit der Maus auf einen Balken, erscheint ein Tooltip mit dem Wert und seiner Einheit. Das gilt ebenso für die Segmente der Ringdiagramme in den übrigen Reitern; dort nennt der Tooltip zusätzlich den Anteil in Prozent.</p><h3 id="_4-2-3-rohre" tabindex="-1">4.2.3 Rohre <a class="header-anchor" href="#_4-2-3-rohre" aria-label="Permalink to &quot;4.2.3 Rohre&quot;">​</a></h3><p>Der Reiter „Rohre“ beginnt mit dem Kasten „Top 5 längste Rohre“, der Rang, Name, Typ und Länge der fünf längsten Rohre nennt; sind keine Rohre vorhanden, fehlt der Kasten. Darunter folgen die Diagramme:</p><ul><li>„Länge nach Rohrtyp“</li><li>„Länge nach Status und Typ“ – gestapelte Balken; die Legende über dem Diagramm erklärt, welche Farbe zu welchem Rohrtyp gehört</li><li>„Gesamtlänge pro Netzebene“ – Ringdiagramm</li><li>„Durchschnittliche Länge nach Typ“</li><li>„Anzahl Rohre nach Status“</li><li>„Länge nach Eigentümer“</li><li>„Länge nach Hersteller“ – Ringdiagramm</li><li>„Rohre im Zeitverlauf“ – Anzahl der Rohre je Monat</li></ul><p><img src="'+u+'" alt="Screenshot Dashboard mit Hervorhebung der Auswertungen im Reiter „Rohre“ in der Inhaltsfläche" data-zoomable="true"></p><p>Angelegt und bearbeitet werden Rohre im Bereich Rohrverwaltung, siehe Kapitel <a href="./06-rohrverwaltung.html">Rohrverwaltung</a>.</p><h3 id="_4-2-4-netzknoten" tabindex="-1">4.2.4 Netzknoten <a class="header-anchor" href="#_4-2-4-netzknoten" aria-label="Permalink to &quot;4.2.4 Netzknoten&quot;">​</a></h3><p>Der Reiter „Netzknoten“ enthält sechs waagerechte Balkendiagramme: „Netzknoten nach Ort“, „Netzknoten nach Status“, „Netzknoten nach Netzebene“, „Netzknoten nach Typ“, „Netzknoten nach Eigentümer“ und „Neueste Netzknoten“.</p><p><img src="'+m+'" alt="Screenshot Dashboard mit Hervorhebung der Diagramme im Reiter „Netzknoten“ in der Inhaltsfläche" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>„Neueste Netzknoten“ ist eine Aufzählung, keine Mengenauswertung. Das Diagramm listet die fünf zuletzt datierten Netzknoten mit Namen und Typ auf; alle Balken sind deshalb gleich lang. Netzknoten, bei denen die jeweilige Angabe fehlt, bleiben in allen Diagrammen unberücksichtigt – die Summe der Balken muss daher nicht der Gesamtzahl aus dem Reiter „Übersicht“ entsprechen.</p></div><h3 id="_4-2-5-adressen" tabindex="-1">4.2.5 Adressen <a class="header-anchor" href="#_4-2-5-adressen" aria-label="Permalink to &quot;4.2.5 Adressen&quot;">​</a></h3><p>Der Reiter „Adressen“ enthält vier Diagramme: „Adressen nach Ort“, „Adressen nach Ausbaustatus“ und „Wohneinheiten nach Ort“ als waagerechte Balken sowie „Wohneinheiten nach Typ“ als Ringdiagramm.</p><p><img src="'+b+'" alt="Screenshot Dashboard mit Hervorhebung der Diagramme im Reiter „Adressen“ in der Inhaltsfläche" data-zoomable="true"></p><h3 id="_4-2-6-gebiete" tabindex="-1">4.2.6 Gebiete <a class="header-anchor" href="#_4-2-6-gebiete" aria-label="Permalink to &quot;4.2.6 Gebiete&quot;">​</a></h3><p>Der Reiter „Gebiete“ zeigt, wie viele Gebiete im Projekt hinterlegt sind und welcher Anteil des Bestands innerhalb dieser Gebiete liegt. In der ersten Reihe stehen die Karten „Anzahl Gebiete“, „Gesamtfläche“ und „Gebiete nach Typ“ als Ringdiagramm.</p><p>Darunter folgen drei Karten zur <strong>Abdeckung</strong> – „Adress-Abdeckung“, „Netzknoten-Abdeckung“ und „Wohneinheiten-Abdeckung“. Jede nennt den Wert innerhalb der Gebiete und, durch einen Schrägstrich getrennt, den Gesamtwert des Projekts; darunter steht der auf ganze Zahlen gerundete Anteil in Prozent.</p><p>Den unteren Block bilden sechs waagerechte Balkendiagramme: „Adressen pro Gebiet“, „Adressen nach Gebietstyp“, „Netzknoten pro Gebiet“, „Netzknoten nach Gebietstyp“, „Trassenlänge pro Gebiet“ und „Wohneinheiten nach Gebietstyp“.</p><p><img src="'+p+'" alt="Screenshot Dashboard mit Hervorhebung der Karten und Diagramme im Reiter „Gebiete“ in der Inhaltsfläche" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Diagramme „Adressen pro Gebiet“, „Netzknoten pro Gebiet“ und „Trassenlänge pro Gebiet“ zeigen höchstens die zehn Gebiete mit den höchsten Werten. Bei mehr als zehn Gebieten ist die Auswertung also keine vollständige Liste.</p></div>',50)])])}const G=n(f,[["render",k]]);export{R as __pageData,G as default};
